    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #81c784;margin-bottom:20px;">
    <h3 style="color:#e8f5e9;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Soil pollution at home is controlled by sorting waste and disposing of each type safely: waste water into a soak pit, chemical containers as labels direct or to collection points, plastics through the 3 Rs, and kitchen waste into a compost pit. Plastics and chemical containers must never be burnt.</p>
    <h4 style="color:#e8f5e9;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Soak pits.</li>
    <li>Chemical containers.</li>
    <li>3 Rs.</li>
    <li>Compost pit.</li>
    </ul>
    </div>
