    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">1. Mark</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Peg the contour with an A-frame</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Peg pit positions along the contour</td>
    </tr>
