    <ul style="margin:6px 0;padding-left:22px;">
    <li>Wear protective clothing such as gloves, gumboots and an apron for garden and kitchen work.</li>
    <li>Carry and use garden tools safely, pointing sharp edges down, and clean and store them after use.</li>
    <li>Never handle farm chemicals or fertilizers without an adult; wash your hands after any garden or kitchen task.</li>
    <li>Report any injury to the teacher at once.</li>
    </ul>
